8	// poseShift 描述一次回环校正对轨迹施加的同一次刚体重定位：锚点落到目标
9	// 位置、朝向归一到 [-π,π)；从锚点到末帧的其余帧与锚点一起平移旋转，保留
10	// 各帧相对锚点的位置关系与朝向差。提交校正（Correct）与打开地图时的校正
11	// 记录几何核对（validateLoaded，见 persistence.go）共用这同一份规则与
12	// 运算次序，两处对“校正后位置与朝向”的理解因此始终一致。
13	type poseShift struct {
14		x, y       float64 // 目标位置，即锚点校正后位置
15		heading    float64 // 目标朝向归一到 [-π,π)，即锚点校正后朝向
16		anchorX    float64 // 锚点校正前位置
17		anchorY    float64
18		dHeading   float64 // 归一后的最短朝向差，即各帧叠加的旋转角
19		cosD, sinD float64 // 旋转角的余弦与正弦
20		identity   bool    // 只调方差的恒等校正：位置与朝向保持原值
21	}
22	
23	// newPoseShift 按提交目标与锚点校正前位姿构造重定位。目标朝向先归一，
24	// 旋转角取归一后的最短朝向差。目标位置与锚点原位置完全相同、目标朝向归
25	// 一后与原朝向等价（旋转角为 0）时是恒等校正：几何上没有任何平移或旋
26	// 转，校正前后位姿必须完全相同。恒等校正不能套用旋转平移公式——公式会
27	// 先求相对锚点的偏移，轨迹横跨 ±1e308 这类大坐标时该差值先溢出为
28	// ±Inf、再参与浮点运算退化为 NaN，使本应成功的校正被误判为数值异常；
29	// 恒等校正直接保留原位姿。
30	func newPoseShift(tgt CorrectionTarget, anchorBefore Pose) poseShift {
31		heading := normalizeAngle(tgt.Heading)
32		dHeading := normalizeAngle(heading - anchorBefore.Heading)
33		return poseShift{
34			x:        tgt.X,
35			y:        tgt.Y,
36			heading:  heading,
37			anchorX:  anchorBefore.X,
38			anchorY:  anchorBefore.Y,
39			dHeading: dHeading,
40			cosD:     math.Cos(dHeading),
41			sinD:     math.Sin(dHeading),
42			identity: dHeading == 0 && tgt.X == anchorBefore.X && tgt.Y == anchorBefore.Y,
43		}
44	}
