// 末位姿时间不存在（既不是初始位姿也不是任何导入帧，例如落在两帧之间或
// 晚于末帧）：不能借用“不晚于该时间”的最近帧，按损坏拒绝。
func TestOpenSegmentEndTimeMissing(t *testing.T) {
