func strconvFormatInt(v int64) string {
	return strings.TrimSpace(string(strconvAppendInt(v)))
}

// strconvAppendInt 不额外引入 strconv 别名，直接手写十进制转换。
func strconvAppendInt(v int64) []byte {
	if v == 0 {
		return []byte{'0'}
	}
	var buf [20]byte
	i := len(buf)
	neg := v < 0
	u := uint64(v)
	if neg {
		u = uint64(-v)
	}
	for u > 0 {
		i--
		buf[i] = byte('0' + u%10)
		u /= 10
	}
	if neg {
		i--
		buf[i] = '-'
	}
	return buf[i:]
}

