1003		// 段首次导入结果核对。每个已保存段的末位姿时间必须准确对应一个已导入
1004		// 帧：trajectory[0] 是初始位姿，不是任何段的末帧；也不能借用时间查询
1005		// “不晚于指定时间”的最近帧——时间没有逐字命中某个已导入帧即按损坏
1006		// 拒绝。这一项只依赖保存的轨迹时间，纯旧文件（缺省 sources）同样适用。
1007		//
1008		// 末位姿的位置、朝向与方差必须等于该段首次成功导入时的末位姿：若该帧
1009		// 从未受到校正，就是它保存的原始位姿；一旦受到校正，则是它首次受到校
1010		// 正前的位姿——按提交次序第一条锚点不晚于该帧、结束时间不早于该帧的校
1011		// 正记录的 Before 快照，不是任意一次校正后的值，也不是当前轨迹位姿。
1012		// 对相同帧多次校正、校正范围只覆盖旧段的一部分、校正之后继续导入新
1013		// 段，都不改写旧段的首次结果；范围没有包含该末帧的校正同样不改变它。
1014		// 位置比较沿用与校正记录几何核对相同的浮点容差（coordClose，与路标合
1015		// 并距离无关），朝向按最短角度差比较（angleClose），方差必须精确一致。
1016		//
1017		// 仅当该末帧与（若有）最早覆盖它的校正范围都具有完整逐帧依据时才核对
1018		// 数值：覆盖范围含 null 旧帧时第一次校正的 Before 快照无法确认，保留
1019		// 旧文件的既有打开规则；末帧本身来自 null 旧帧时其原始位姿同样无从核
1020		// 对。兼容只跳过数值一致性，末位姿时间仍须命中真实导入帧；旧地图之后
1021		// 新追加且依据完整的段照常核对。
1022		for _, sg := range fd.Segments {
1023			end := sg.Result.EndPose.Time
1024			endIdx := -1
1025			for j := 1; j < len(fd.Trajectory); j++ {
1026				if fd.Trajectory[j].Time == end {
1027					endIdx = j
1028					break
1029				}
1030			}
1031			if endIdx < 0 {
1032				return fmt.Errorf("%w: segment %s end pose time %d does not match an imported frame", ErrCorrupt, sg.ID, end)
1033			}
1034			if !finitePose(sg.Result.EndPose) {
1035				return fmt.Errorf("%w: segment %s end pose at frame time %d is non-finite", ErrCorrupt, sg.ID, end)
1036			}
1037			// 找按提交次序第一条覆盖该末帧的校正记录。前面已核对过每条记录的
1038			// 锚点/结束时间都命中已导入帧、锚点不晚于结束时间且条目完整覆盖其
1039			// 范围，这里直接按时间包含关系判断即可。
1040			firstCovering := -1
1041			for i := range fd.Corrections {
1042				cr := fd.Corrections[i]
1043				if cr.Anchor <= end && end <= cr.EndTime {
1044					firstCovering = i
1045					break
1046				}
1047			}
1048			// 数值核对所需依据：末帧必须有逐帧来源；最早覆盖它的校正范围（若
1049			// 有）内每个来源帧都非 null——否则该记录的 Before 快照无法由依据
1050			// 确认。与校正记录核对相同，纯旧文件缺省 sources 时整体不核对数值。
1051			based := len(fd.Sources) != 0 && fd.Sources[endIdx-1] != nil
1052			var anchorIdx, coverEndIdx int
1053			if based && firstCovering >= 0 {
1054				cr := fd.Corrections[firstCovering]
1055				anchorIdx, coverEndIdx = -1, -1
1056				for j := 1; j < len(fd.Trajectory); j++ {
1057					if fd.Trajectory[j].Time == cr.Anchor {
1058						anchorIdx = j
1059					}
1060					if fd.Trajectory[j].Time == cr.EndTime {
1061						coverEndIdx = j
1062					}
1063				}
1064				for k := anchorIdx - 1; k <= coverEndIdx-1; k++ {
1065					if fd.Sources[k] == nil {
1066						based = false
1067						break
1068					}
1069				}
1070			}
1071			if !based {
1072				continue
1073			}
1074			// 首次导入末位姿：无覆盖校正时取当前保存的原始位姿；否则取第一条
1075			// 覆盖记录中该帧的 Before 快照（记录条目与帧一一对应已在前面核
1076			// 对）。不能用该记录的 After 或当前轨迹位姿替换原结果。
1077			var want Pose
1078			if firstCovering < 0 {
1079				want = fd.Trajectory[endIdx]
1080			} else {
1081				want = fd.Corrections[firstCovering].Poses[endIdx-anchorIdx].Before
1082			}
1083			got := sg.Result.EndPose
1084			if !coordClose(got.X, want.X) || !coordClose(got.Y, want.Y) {
1085				return fmt.Errorf("%w: segment %s end pose at frame time %d is saved at (%v,%v) but its first import ended at (%v,%v)", ErrCorrupt, sg.ID, end, got.X, got.Y, want.X, want.Y)
1086			}
1087			if !angleClose(got.Heading, want.Heading) {
1088				return fmt.Errorf("%w: segment %s end pose at frame time %d has saved heading %v but its first import heading was %v", ErrCorrupt, sg.ID, end, got.Heading, want.Heading)
1089			}
1090			if got.Variance != want.Variance {
1091				return fmt.Errorf("%w: segment %s end pose at frame time %d has saved variance %v but its first import variance was %v", ErrCorrupt, sg.ID, end, got.Variance, want.Variance)
1092			}
1093		}
1094		return nil
1095	}
